steps.cmd:
git switch -q -c learn/echo-office && cat > src/example_server/tools/echo_office.py <<'EOF'
from typing import Annotated

from fastmcp import FastMCP
from pydantic import Field


def register(mcp: FastMCP) -> None:
    @mcp.tool(name="echo_office", annotations={"readOnlyHint": True})
    async def echo_office(
        name: Annotated[str, Field(description="An office name.")],
    ) -> dict:
        """Echo an office name back. A learning tool; it reads nothing."""
        return {"office": name.strip().upper()}
EOF
perl -0pi -e 's/from example_server.tools import example_tool\n/from example_server.tools import echo_office, example_tool\n/; s/    example_tool.register\(mcp\)\n/    example_tool.register(mcp)\n    echo_office.register(mcp)\n/' src/example_server/tools/__init__.py && git diff --stat

